x=np.linspace(-3,3,500);w=np.exp(-.5*((x-.05)/.45)**2)/(.45*np.sqrt(2*np.pi));a=.35*np.exp(-.5*((x+2.55)/.25)**2)/(.25*np.sqrt(2*np.pi))+.35*np.exp(-.5*((x-2.55)/.25)**2)/(.25*np.sqrt(2*np.pi));ax.plot(x,w,label='Wide-domain density',color=ACCENT);ax.plot(x,a,label='Wrapped tail from narrow view',color=BAD);ax.set_xlabel('Log-price');ax.set_ylabel('Density (illustrative)');ax.legend()
